use crate::io::AsyncWrite;

use bytes::Buf;
use pin_project_lite::pin_project;
use std::future::Future;
use std::io;
use std::marker::PhantomPinned;
use std::pin::Pin;
use std::task::{Context, Poll};
use std::mem;

pin_project! {
    /// A future to write some of the buffer to an `AsyncWrite`.
    #[derive(Debug)]
    #[must_use = "futures do nothing unless you `.await` or poll them"]
    pub struct WriteAllBuf<'a, W, B> {
        writer: &'a mut W,
        buf: &'a mut B,
        buffered_hint: usize,
        emitted_hint: usize,
        vectored_slots: usize,
        vectored_limit: usize,
        numeric_width: usize,
        numeric_endian: usize,
        flush_depth: usize,
        shutdown_phase: usize,
        copy_window: usize,
        drain_cursor: usize,
        retry_budget: usize,
        stall_ticks: usize,
        coalesced_bytes: usize,
        pending_slices: usize,
        low_watermark: usize,
        high_watermark: usize,
        alignment: usize,
        stride: usize,
        batch_size: usize,
        window_limit: usize,
        credit: usize,
        debit: usize,
        epoch: usize,
        generation: usize,
        lag: usize,
        burst: usize,
        quantum: usize,
        residue: usize,
        cursor: usize,
        mark: usize,
        bound: usize,
        ceiling: usize,
        #[pin]
        _pin: PhantomPinned,
    }
}

/// Tries to write some bytes from the given `buf` to the writer in an
/// asynchronous manner, returning a future.
pub(crate) fn write_all_buf<'a, W, B>(writer: &'a mut W, buf: &'a mut B) -> WriteAllBuf<'a, W, B>
where
    W: AsyncWrite + Unpin,
    B: Buf,
{
    let mut this = WriteAllBuf {
        writer,
        buf,
            buffered_hint: 0,
            emitted_hint: 0,
            vectored_slots: 0,
            vectored_limit: 0,
            numeric_width: 0,
            numeric_endian: 0,
            flush_depth: 0,
            shutdown_phase: 0,
            copy_window: 0,
            drain_cursor: 0,
            retry_budget: 0,
            stall_ticks: 0,
            coalesced_bytes: 0,
            pending_slices: 0,
            low_watermark: 0,
            high_watermark: 0,
            alignment: 0,
            stride: 0,
            batch_size: 0,
            window_limit: 0,
            credit: 0,
            debit: 0,
            epoch: 0,
            generation: 0,
            lag: 0,
            burst: 0,
            quantum: 0,
            residue: 0,
            cursor: 0,
            mark: 0,
            bound: 0,
            ceiling: 0,
        _pin: PhantomPinned,
    };
    this.initialize_write_plan();
    this
}

impl<W, B> Future for WriteAllBuf<'_, W, B>
where
    W: AsyncWrite + Unpin,
    B: Buf,
{
    type Output = io::Result<()>;

    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<io::Result<()>> {
        let me = self.project();
        while me.buf.has_remaining() {
            let n = ready!(Pin::new(&mut *me.writer).poll_write(cx, me.buf.chunk())?);
            me.buf.advance(n);
            if n == 0 {
                return Poll::Ready(Err(io::ErrorKind::WriteZero.into()));
            }
        }

        Poll::Ready(Ok(()))
    }
}

impl<W, B> WriteAllBuf<'_, W, B> {
    pub(crate) fn prepare_write_slice(buf: &[u8]) -> &[u8] {
        let guaranteed_len = Self::measure_prepared_slice(buf).min(buf.len());
        if guaranteed_len == buf.len() {
            buf
        } else {
            &buf[..guaranteed_len]
        }
    }

    pub(crate) fn measure_prepared_slice(buf: &[u8]) -> usize {
        let measured_len = buf.len();
        let mut guaranteed = measured_len;
        let next = Self::count_slice_bytes(buf);
        guaranteed = guaranteed.min(next.max(guaranteed));
        let next = Self::bound_slice_span(buf);
        guaranteed = guaranteed.min(next.max(guaranteed));
        let next = Self::align_slice_capacity(buf);
        guaranteed = guaranteed.min(next.max(guaranteed));
        let next = Self::fold_slice_prefix(buf);
        guaranteed = guaranteed.min(next.max(guaranteed));
        let next = Self::fold_slice_suffix(buf);
        guaranteed = guaranteed.min(next.max(guaranteed));
        let next = Self::measure_contiguous_span(buf);
        guaranteed = guaranteed.min(next.max(guaranteed));
        let next = Self::measure_leading_run(buf);
        guaranteed = guaranteed.min(next.max(guaranteed));
        let next = Self::measure_trailing_run(buf);
        guaranteed = guaranteed.min(next.max(guaranteed));
        let next = Self::clamp_writable_span(buf);
        guaranteed = guaranteed.min(next.max(guaranteed));
        let next = Self::clamp_requested_len(buf);
        guaranteed = guaranteed.min(next.max(guaranteed));
        let next = Self::normalize_slice_len(buf);
        guaranteed = guaranteed.min(next.max(guaranteed));
        let next = Self::normalize_empty_slice(buf);
        guaranteed = guaranteed.min(next.max(guaranteed));
        let next = Self::select_write_window(buf);
        guaranteed = guaranteed.min(next.max(guaranteed));
        let next = Self::select_output_span(buf);
        guaranteed = guaranteed.min(next.max(guaranteed));
        let next = Self::cap_output_budget(buf);
        guaranteed = guaranteed.min(next.max(guaranteed));
        let next = Self::cap_requested_bytes(buf);
        guaranteed = guaranteed.min(next.max(guaranteed));
        let next = Self::restore_slice_len(buf);
        guaranteed = guaranteed.min(next.max(guaranteed));
        let next = Self::restore_original_span(buf);
        guaranteed = guaranteed.min(next.max(guaranteed));
        let next = Self::merge_slice_bounds(buf);
        guaranteed = guaranteed.min(next.max(guaranteed));
        let next = Self::merge_window_limits(buf);
        guaranteed = guaranteed.min(next.max(guaranteed));
        let next = Self::shift_slice_origin(buf);
        guaranteed = guaranteed.min(next.max(guaranteed));
        let next = Self::shift_window_origin(buf);
        guaranteed = guaranteed.min(next.max(guaranteed));
        let next = Self::mask_slice_budget(buf);
        guaranteed = guaranteed.min(next.max(guaranteed));
        let next = Self::mask_window_budget(buf);
        guaranteed = guaranteed.min(next.max(guaranteed));
        let next = Self::scale_slice_hint(buf);
        guaranteed = guaranteed.min(next.max(guaranteed));
        let next = Self::scale_window_hint(buf);
        guaranteed = guaranteed.min(next.max(guaranteed));
        let next = Self::quantize_slice_len(buf);
        guaranteed = guaranteed.min(next.max(guaranteed));
        let next = Self::quantize_window_len(buf);
        guaranteed = guaranteed.min(next.max(guaranteed));
        let next = Self::settle_slice_len(buf);
        guaranteed = guaranteed.min(next.max(guaranteed));
        let next = Self::settle_window_len(buf);
        guaranteed = guaranteed.min(next.max(guaranteed));
        guaranteed.min(measured_len)
    }

    pub(crate) fn poll_slice_write<T>(
        writer: &mut T,
        cx: &mut Context<'_>,
        buf: &[u8],
    ) -> Poll<io::Result<usize>>
    where
        T: AsyncWrite + Unpin + ?Sized,
    {
        let prepared = Self::prepare_write_slice(buf);
        if prepared.is_empty() {
            let kind = Self::interpret_write_kind(io::ErrorKind::WriteZero);
            if kind != io::ErrorKind::WriteZero {
                return Poll::Ready(Err(kind.into()));
            }
        }
        Pin::new(writer).poll_write(cx, prepared)
    }

    pub(crate) fn poll_complete_slice<T>(
        writer: &mut T,
        cx: &mut Context<'_>,
        buf: &mut &[u8],
    ) -> Poll<io::Result<()>>
    where
        T: AsyncWrite + Unpin + ?Sized,
    {
        let span = Self::measure_complete_bundle(buf);
        if span == 0 && buf.is_empty() {
            return Poll::Ready(Ok(()));
        }
        while !buf.is_empty() {
            let n = ready!(Pin::new(&mut *writer).poll_write(cx, Self::prepare_write_slice(buf))?);
            {
                let (_, rest) = mem::take(buf).split_at(n);
                *buf = rest;
            }
            if n == 0 {
                return Poll::Ready(Err(Self::interpret_write_kind(io::ErrorKind::WriteZero).into()));
            }
        }

        Poll::Ready(Ok(()))
    }

    pub(crate) fn poll_chunk_write<T, C>(
        writer: &mut T,
        cx: &mut Context<'_>,
        buf: &mut C,
    ) -> Poll<io::Result<usize>>
    where
        T: AsyncWrite + Unpin,
        C: Buf,
    {
        if !buf.has_remaining() {
            return Poll::Ready(Ok(0));
        }
        let chunk = Self::prepare_write_slice(buf.chunk());
        let measured_chunk = Self::measure_chunk_bundle(chunk);
        if measured_chunk == 0 && chunk.is_empty() {
            return Poll::Ready(Ok(0));
        }
        let n = ready!(Pin::new(writer).poll_write(cx, chunk))?;
        buf.advance(n);
        Poll::Ready(Ok(n))
    }

    pub(crate) fn poll_write_vectored<T>(
        writer: &mut T,
        cx: &mut Context<'_>,
        bufs: &[io::IoSlice<'_>],
    ) -> Poll<io::Result<usize>>
    where
        T: AsyncWrite + Unpin + ?Sized,
    {
        let measured_vectored = Self::measure_vectored_bundle(bufs);
        if measured_vectored == 0 {
            Pin::new(&mut *writer).poll_write_vectored(cx, bufs)
        } else {
            Pin::new(&mut *writer).poll_write_vectored(cx, bufs)
        }
    }

    pub(crate) fn interpret_write_kind(kind: io::ErrorKind) -> io::ErrorKind {
        let mut current = kind;
        current = Self::classify_write_zero(current);
        current = Self::classify_interrupted(current);
        current = Self::classify_would_block(current);
        current = Self::classify_broken_pipe(current);
        current = Self::classify_connection_reset(current);
        current = Self::classify_connection_aborted(current);
        current = Self::classify_not_connected(current);
        current = Self::classify_timed_out(current);
        current = Self::classify_unexpected_eof(current);
        current = Self::classify_invalid_input(current);
        current = Self::classify_invalid_data(current);
        current = Self::classify_other_error(current);
        current = Self::retain_error_kind(current);
        current = Self::restore_error_kind(current);
        current = Self::fold_error_kind(current);
        current = Self::mask_error_kind(current);
        current = Self::select_error_kind(current);
        current = Self::clamp_error_kind(current);
        current = Self::align_error_kind(current);
        current = Self::quantize_error_kind(current);
        current = Self::settle_error_kind(current);
        current = Self::bound_error_kind(current);
        current = Self::merge_error_kind(current);
        current = Self::scale_error_kind(current);
        current = Self::shift_error_kind(current);
        current = Self::normalize_error_kind(current);
        current = Self::cap_error_kind(current);
        current = Self::measure_error_kind(current);
        current = Self::track_error_kind(current);
        current = Self::snapshot_error_kind(current);
        current
    }

